import React, { useState, useEffect } from 'react';
import axios from 'axios';

const MovieList = () => {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');

  useEffect(() => {
    fetchMovies();
  }, []);

  const fetchMovies = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/movies');
      setMovies(response.data);
    } catch (error) {
      console.error('Error fetching movies:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredMovies = movies.filter(movie => {
    const matchesSearch = movie.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesGenre = !selectedGenre || movie.genre === selectedGenre;
    return matchesSearch && matchesGenre;
  });

  const genres = [...new Set(movies.map(movie => movie.genre))];

  const handleBookMovie = (movie) => {
    // This would typically navigate to booking page
    alert(`Booking feature coming soon for: ${movie.title}`);
  };

  if (loading) {
    return (
      <div className="container">
        <div style={{ textAlign: 'center', padding: '2rem' }}>
          <h2>🍿 Loading Movies...</h2>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ color: 'white', marginBottom: '1rem' }}>🎬 Now Showing</h1>

        <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem', flexWrap: 'wrap' }}>
          <input
            type="text"
            placeholder="🔍 Search movies..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="form-input"
            style={{ flex: 1, minWidth: '200px' }}
          />

          <select
            value={selectedGenre}
            onChange={(e) => setSelectedGenre(e.target.value)}
            className="form-input"
            style={{ minWidth: '150px' }}
          >
            <option value="">All Genres</option>
            {genres.map(genre => (
              <option key={genre} value={genre}>{genre}</option>
            ))}
          </select>
        </div>
      </div>

      {filteredMovies.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '2rem', color: 'white' }}>
          <h2>🎭 No movies found</h2>
          <p>Try adjusting your search or filter criteria</p>
        </div>
      ) : (
        <div className="movie-grid">
          {filteredMovies.map(movie => (
            <div key={movie.movieId} className="movie-card" onClick={() => handleBookMovie(movie)}>
              <div className="movie-poster">
                {movie.posterUrl ? (
                  <img src={movie.posterUrl} alt={movie.title} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                ) : (
                  <span>🎬</span>
                )}
              </div>
              <div className="movie-info">
                <h3 className="movie-title">{movie.title}</h3>
                <p className="movie-genre">🎭 {movie.genre}</p>
                <p className="movie-description">{movie.description}</p>
                <div className="movie-meta">
                  <span className="movie-price">${movie.price}</span>
                  <span className="movie-duration">⏱️ {movie.durationMinutes}min</span>
                </div>
                {movie.rating && (
                  <div style={{ marginTop: '0.5rem' }}>
                    ⭐ {movie.rating}/10
                  </div>
                )}
                <button 
                  className="btn btn-primary"
                  style={{ marginTop: '1rem', width: '100%' }}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleBookMovie(movie);
                  }}
                >
                  🎫 Book Now
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MovieList;
